export const STUDENT_MOBILE_BOTTOM_NAV_HEIGHT = 76;
export const STUDENT_MOBILE_PANEL_EDGE_GAP = 12;

/** Height available to a Student Map sheet above its header and fixed navigation. */
export function studentMobilePanelAvailableHeight(
  viewportHeight: number,
  reservedTop: number,
  safeAreaBottom = 0,
  bottomNavigationHeight = STUDENT_MOBILE_BOTTOM_NAV_HEIGHT,
  edgeGap = STUDENT_MOBILE_PANEL_EDGE_GAP,
): number {
  if (!Number.isFinite(viewportHeight) || viewportHeight <= 0) return 0;
  const top = Number.isFinite(reservedTop) ? Math.max(0, reservedTop) : 0;
  const safeBottom = Number.isFinite(safeAreaBottom) ? Math.max(0, safeAreaBottom) : 0;
  return Math.max(0, viewportHeight - top - safeBottom - bottomNavigationHeight - edgeGap);
}
import { describe, expect, it } from "vitest";
import { studentMobilePanelAvailableHeight } from "../studentMobilePanels";

describe("Student Map mobile panel bounds", () => {
  it.each([
    [568, 108, 0],
    [640, 108, 20],
    [664, 112, 0],
    [700, 116, 24],
  ])("reserves the header, bottom navigation, and safe area at %ipx viewport height", (height, top, safeBottom) => {
    expect(studentMobilePanelAvailableHeight(height, top, safeBottom))
      .toBe(Math.max(0, height - top - safeBottom - 76 - 12));
  });

  it("returns no negative panel space for very short or invalid viewports", () => {
    expect(studentMobilePanelAvailableHeight(140, 120, 24)).toBe(0);
    expect(studentMobilePanelAvailableHeight(Number.NaN, 120, 24)).toBe(0);
  });
});
