export function routeDoorTransitOpacity(
  progress: number,
  active: boolean,
  measure: RouteDoorCrossingMeasure,
  radius = ROUTE_DOOR_TRANSIT_RADIUS,
  opacity = ROUTE_DOOR_TRANSIT_OPACITY,
): number {
